int _int(dynamic value) => value is int ? value : int.parse(value.toString());

class Program { final int programId; final String programCode, programName; const Program({required this.programId, required this.programCode, required this.programName}); Program copyWith({int? programId,String? programCode,String? programName})=>Program(programId:programId??this.programId,programCode:programCode??this.programCode,programName:programName??this.programName); factory Program.fromJson(Map<String,dynamic> j)=>Program(programId:_int(j['ProgramId']),programCode:j['ProgramCode'] as String,programName:j['ProgramName'] as String); Map<String,dynamic> toJson()=>{'ProgramId':programId,'ProgramCode':programCode,'ProgramName':programName}; }
